def match(orders):
    import heapq

    buy_heap = []   # (-price, seq, id)
    sell_heap = []  # (price, seq, id)
    book = {}       # id -> {'side','price','qty','seq','status'}
    trades = []
    seq_counter = 0

    for o in orders:
        typ = o[0]

        if typ == 'cancel':
            oid = o[1]
            info = book.get(oid)
            if info is not None and info['status'] == 'active' and info['qty'] > 0:
                info['status'] = 'cancelled'
            continue

        if typ == 'limit':
            _, oid, side, price, qty = o
        elif typ == 'ioc':
            _, oid, side, price, qty = o
        elif typ == 'market':
            _, oid, side, qty = o
            price = None
        else:
            # unknown type, ignore
            continue

        seq = seq_counter
        seq_counter += 1

        remaining = qty

        if side == 'buy':
            heap = sell_heap
            while remaining > 0 and heap:
                top_price, top_seq, top_id = heap[0]
                info = book.get(top_id)
                if info is None or info['status'] != 'active' or info['qty'] <= 0:
                    heapq.heappop(heap)
                    continue
                if typ != 'market' and top_price > price:
                    break
                trade_qty = min(remaining, info['qty'])
                trades.append([oid, top_id, top_price, trade_qty])
                remaining -= trade_qty
                info['qty'] -= trade_qty
                if info['qty'] == 0:
                    info['status'] = 'filled'
                    heapq.heappop(heap)
                # if info['qty'] > 0, remaining must be 0, loop will end naturally

            if typ == 'limit' and remaining > 0:
                book[oid] = {'side': 'buy', 'price': price, 'qty': remaining, 'seq': seq, 'status': 'active'}
                heapq.heappush(buy_heap, (-price, seq, oid))

        else:  # sell
            heap = buy_heap
            while remaining > 0 and heap:
                neg_price, top_seq, top_id = heap[0]
                top_price = -neg_price
                info = book.get(top_id)
                if info is None or info['status'] != 'active' or info['qty'] <= 0:
                    heapq.heappop(heap)
                    continue
                if typ != 'market' and top_price < price:
                    break
                trade_qty = min(remaining, info['qty'])
                trades.append([top_id, oid, top_price, trade_qty])
                remaining -= trade_qty
                info['qty'] -= trade_qty
                if info['qty'] == 0:
                    info['status'] = 'filled'
                    heapq.heappop(heap)

            if typ == 'limit' and remaining > 0:
                book[oid] = {'side': 'sell', 'price': price, 'qty': remaining, 'seq': seq, 'status': 'active'}
                heapq.heappush(sell_heap, (price, seq, oid))

    return trades

